CREATE TABLE public.conversation_notification_prefs (id UUID NOT NULL DEFAULT gen_random_uuid() PRIMARY KEY, conversation_id UUID NOT NULL, user_id UUID NOT NULL, muted_until TIMESTAMPTZ, sound TEXT, vibration_pattern TEXT, importance TEXT NOT NULL DEFAULT 'default', native_channel_id TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE (conversation_id, user_id)); CREATE INDEX idx_convo_notif_prefs_user ON public.conversation_notification_prefs(user_id); ALTER TABLE public.conversation_notification_prefs ENABLE ROW LEVEL SECURITY; CREATE POLICY "notif_read_own" ON public.conversation_notification_prefs FOR SELECT TO authenticated USING (auth.uid() = user_id); CREATE POLICY "notif_insert_own" ON public.conversation_notification_prefs FOR INSERT TO authenticated WITH CHECK (auth.uid() = user_id); CREATE POLICY "notif_update_own" ON public.conversation_notification_prefs FOR UPDATE TO authenticated USING (auth.uid() = user_id); CREATE POLICY "notif_delete_own" ON public.conversation_notification_prefs FOR DELETE TO authenticated USING (auth.uid() = user_id); CREATE TRIGGER trg_convo_notif_prefs_updated BEFORE UPDATE ON public.conversation_notification_prefs FOR EACH ROW EXECUTE FUNCTION public.update_updated_at_column();